// ~60-day token with NO programmatic refresh - a rejected token is a
// terminal instruction to re-run the browser OAuth re-issue flow, not
// a retryable condition. The client secret backs that flow only and
// never rides a request, but it still joins KNOWN_TOKENS so an echoed
// error string cannot leak it.
const LI_TOKEN = ENV('LINKEDIN_ACCESS_TOKEN') || null;
if (LI_TOKEN) KNOWN_TOKENS.add(LI_TOKEN);
