// platform's own status file so a LinkedIn failure never rewrites
// the VK headline (and vice versa)
const liStatus = (s, reason, file) => {
  liTickFiles.push({ file: file || '', status: s, reason: reason || '' });
  try {
    const now = new Date().toISOString();
    writeJsonAtomic(LI_STATUS, {
      status: s, ts: now, last_tick: now, file: file || '',
      reason: reason || '', files: liTickFiles
    });
  } catch (e) {}
};
// transient LinkedIn answers: a definite server-side rejection, so
// the post provably never ran and the file can take the same bounded
// requeue as TRANSIENT_VK_CODES. 429 rate limit, 5xx backend blips.
const TRANSIENT_LI_STATUSES = new Set([429, 500, 502, 503, 504]);
