      scrub(e).slice(0, 200));
    e2.li_status = status || undefined;
    if (status === 401 || status === 403) {
      // token rejected (expired/revoked/scope missing) - a definite
      // API answer, so no maybe_live and no requeue: the operator
      // re-runs the browser OAuth re-issue
      e2.li_auth = true;
