// was transport-level (no answer ever arrived - ECONNREFUSED on a
// service restart, host reboot where n8n came up first, timeout,
// slirp gateway blip). The wrapper shapes vary like isBusyRefreshErr
// documents, and as a last resort the status can sit inside the
// message text ('Request failed with status code 502').
const refreshHttpStatus = (e) => {
  if (!e) return 0;
  const status = Number(
    (e.response && e.response.status) || e.statusCode ||
    e.httpCode || e.status);
  if (Number.isFinite(status) && status > 0) return status;
  const m = /status code (\d{3})/i
    .exec(String(e.description || e.message || e));
  return m ? Number(m[1]) : 0;
};
// Retryable refresh failure = the service gave no classified verdict:
// the 503/'busy' lock-contention answer OR a thrown transport error
// carrying no HTTP status (unreachable host). Both are transient and
// wall.post provably never ran in the paths that raise them (the
// no-token throw precedes any VK call; an error-5 rethrow was
// rejected by VK before posting), so the file can safely take the
// same link()-hand-back requeue as busy - BOUNDED by the t.retries
// cap in the tick's catch block. A thrown error WITH a non-503 HTTP
// status is the service's own classified answer (401 bad shared
// secret, 502 'token rejected' - it already decided retryable:false);
// honoring that dead-letters a misconfigured deploy immediately
// instead of burning the retry budget on a permanent failure.
// A .state_write error is NOT a refresh-service answer at all - the
// service minted the token fine and the local state-dir write is
// what threw. Classifying it here would requeue the file up to
// RETRY_MAX and end on a 'token service retry budget exhausted'
// status that points at vk-token.service while the state dir is the
// broken piece; the call sites flag it separately instead.
const isRetryableRefreshErr = (e) =>
  !(e && e.state_write) &&
  (isBusyRefreshErr(e) || !refreshHttpStatus(e));
// transient VK API error codes: the error body is a definite
// server-side answer, so a wall.post carrying one provably never ran
// and requeueing the file on the next tick cannot duplicate a post.
// The set mirrors the retryable side of _check_result in
// tools/vk_token_service.py (every non-5 users.get code is transient
// there): 6 too many requests per second, 9 flood control, 10
// internal server error, 29 rate limit reached, 601 too many actions
// this day - all plausible on multi-file ticks against the ~3 req/s
// wall. Error 5 keeps its refresh-and-retry path; any other unlisted
// code stays terminal so a genuinely permanent rejection still lands
// in failed/.
const TRANSIENT_VK_CODES = new Set([6, 9, 10, 29, 601]);
async function vkRefresh() {
  const r = await http({ method: 'GET', url: REFRESH_URL, json: true, timeout: 60000,
    headers: REFRESH_HEADERS });
  if (r && r.ok && r.access_token) {
    // persist BEFORE installing the token: an install-then-write
    // order leaves a VALID minted token live in vkToken when the
    // state write throws (ENOSPC/EACCES on the state volume - the
    // same volume the queue, ledger, media and logs write to, so a
    // plausible failure). The refresh then counts as failed while
    // the fresh token sits in memory: vkCall's env fallback
    // silently overwrites it with the stale env token for the
    // retry, and the thrown FS error - carrying no HTTP status -
    // is misclassified by isRetryableRefreshErr() as a retryable
    // token-service outage. Write first, install only on success;
    // a write throw is wrapped with .state_write so both call
    // sites report a state-dir failure, not token_service_down.
    try {
      writeJsonAtomic(VK_STATE, {
        access_token: r.access_token,
        saved_at: new Date().toISOString(),
        source: r.source || 'refresh-service'
      });
    } catch (we) {
      const se = new Error('vk token refresh: state write failed - ' +
        String((we && we.message) || we).slice(0, 120));
      se.state_write = true;
      throw se;
    }
    vkToken = r.access_token;
    KNOWN_TOKENS.add(vkToken);
    return true;
  }
  // a RESOLVED non-2xx body is possible whenever the httpRequest
  // wrapper stops throwing on HTTP errors (n8n version or config
  // change): a 503 {retryable:true} 'busy' answer landing here would
  // degrade to a plain 'returned no token' and the file would park in
  // failed/ instead of requeueing. Surface it as a thrown busy error
  // - isBusyRefreshErr reads .body.retryable, so both call sites
  // (the vkCall error-5 refresh and the publishVk no-token refresh)
  // reclassify it without further changes.
  if (r && r.retryable === true) {
    const e = new Error('vk token refresh: service busy - ' +
      scrub(JSON.stringify(r)).slice(0, 150));
    e.body = r;
    throw e;
  }
  return false;
}

async function vkCall(method, params) {
  // access_token travels in the POST body (form-encoded), never in the
  // URL - transport-level errors can echo the request URL back, which
  // would leak the token into logs and the Telegram summary.
  const call = async (t) => {
    const res = await http({
      method: 'POST',
      url: 'https://api.vk.com/method/' + method,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'v=5.199&access_token=' + encodeURIComponent(t) + '&' + params,
      // explicit timeout: httpRequest's default is unbounded, so a hung
      // api.vk.com socket would stall the tick far past the 2-min
      // interval while holding the processing/ claim (the file then
      // looks like a crashed claim to stuck-claim recovery)
      timeout: 30000,
      json: true
    });
    // the VK schema promises an integer error_code, but a proxy or
    // shim in front of api.vk.com can answer it as a string ("5") -
    // the strict === 5 gate below would then skip the refresh+retry
    // branch and park a rejected-token file in failed/ without the
    // self-heal this mechanism exists for. vk_token_service.py
    // int()-normalizes the same code before its own == 5 check; the
    // n8n side shares that network path, so normalize here too -
    // once, so the gate AND every downstream e.vk_code === 5
    // classification read a number. An unparseable code keeps its
    // raw value: coercing it to NaN would turn a weird string code
    // falsy and misclassify it as a transport failure below.
    if (res && res.error) {
      const c = Number(res.error.error_code);
      if (!Number.isNaN(c)) res.error.error_code = c;
    }
    return res;
  };
  let r = await call(vkToken);
  let refreshErr = null;
  if (r && r.error && r.error.error_code === 5) {
    // expired/rejected token - pull a fresh one and retry once. A
    // THROWN refresh error (HTTP failure/timeout against the host
    // service) is a token-service outage, not a VK auth rejection:
    // keeping it lets the re-thrown error-5 below be reclassified as
    // token_service_down, so the operator restarts vk-token.service
    // instead of rotating VK credentials. A resolved-but-false
    // vkRefresh (service answered {ok:false}) stays an auth error -
    // the service is reachable, VK-side minting is what failed.
    let ok = false;
    try { ok = await vkRefresh(); } catch (e) { refreshErr = e; }
    if (ok) {
      r = await call(vkToken);
    } else if (ENV_TOKEN && ENV_TOKEN !== vkToken) {
      // refresh service unreachable or returned no token - last
      // resort: the env token may still be valid even when the
      // cached web-session token is not
      vkToken = ENV_TOKEN;
      r = await call(vkToken);
    }
  }
  if (r && r.error) {
    const e = new Error('vk ' + method + ': ' + scrub(JSON.stringify(r.error)).slice(0, 200));
    e.vk_code = r.error.error_code;
    // a definite error body means VK rejected the call server-side -
    // for wall.post that proves the post never ran, so the rate/flood
    // family requeues bounded by t.retries/RETRY_MAX like the
    // token_service_down path instead of parking in failed/ until a
    // manual re-approve. Only reaches the tick's catch through
    // wall.post: the wall.get/wall.getById/wall.delete callers inside
    // publishVk all swallow or tolerate this throw
    if (TRANSIENT_VK_CODES.has(e.vk_code)) {
      e.retryable = true;
      e.vk_transient = true;
    }
    if (refreshErr && e.vk_code === 5) {
      // this error-5 only stands because the refresh step could not
      // deliver a usable token - report the actionable failure (the
      // VK code is kept for the log line)
      e.refresh_error = scrub(refreshErr).slice(0, 150);
      // BOTH halves can be dead at once: when the token this error-5
      // came from IS the env fallback (the explicit ENV_TOKEN retry
      // above, or the env token was the only token on file from the
      // start), the env credential is rejected too - reporting just
      // 'token_service_down' sends the operator to restart
      // vk-token.service while VK_ACCESS_TOKEN in ENV is what needs
      // rotating. Flag the dual cause so the tick reports a distinct
      // status instead of masking it.
      if (ENV_TOKEN && vkToken === ENV_TOKEN) e.env_token_auth = true;
      if (refreshErr.state_write) {
        // the service DID mint a token - persisting it to the state
        // dir is what failed. A local FS error is neither a
        // token-service outage nor retryable (the requeue hand-back
        // lives on the same volume): flag it so the tick reports
        // state_write_error instead of token_service_down and the
        // file fails pointing at the state dir, not at
        // vk-token.service.
        e.state_write = true;
      } else {
        e.token_service = true;
        // this error-5 only happened because the refresh service
        // could not deliver a verdict - VK rejected the token BEFORE
        // wall.post ran, so no post can be live. A transient refresh
        // failure (busy 503 or unreachable host - see
        // isRetryableRefreshErr) requeues the file for the next tick
        // instead of parking it in failed/, bounded by the t.retries
        // cap there. A classified non-503 service answer stays
        // terminal.
        e.retryable = isRetryableRefreshErr(refreshErr);
        if (isBusyRefreshErr(refreshErr)) e.busy = true;
      }
    }
    throw e;
  }
  return r && r.response;
}

async function publishVk(t, fname) {
  const owner = ENV('VK_USER_ID');
  if (!owner) throw new Error('vk: VK_USER_ID not set');
  // `test` is a strict JSON boolean: only `test === true` triggers the
  // publish-verify-delete test path; "yes"/1 are treated as real posts.
  const isTest = t.test === true;
  // media[] carries the moderation-selected paths (the legacy
  // single-path `image` field counts as one more attachment) - each
  // resolves through the same resolveMedia/underRoot rules the TG
  // preview used, so an entry the preview delivered to the chat is
  // the file this driver attaches to the wall post
  const mediaList = (Array.isArray(t.media) ? t.media : [])
    .concat(t.image ? [t.image] : []);
  // Minimal publish ledger - full registry is issue #12.
  // Never throws: an append failure (ENOSPC/EACCES on the state dir)
  // drops a fallback evidence line into publish.jsonl - a different
  // dir than LEDGER, so a file-level failure still leaves the post id
  // on disk SOMEWHERE - and returns false. The caller decides whether
  // the missing record is fatal: post-created below treats false as
  // fatal-with-flags (a wall.post success with no durable post id is
  // a live orphan), the later verify/published/test records tolerate
  // it because post-created already holds external_id.
  const ledger = (r) => {
    const rec = {
      ts: new Date().toISOString(), id: t.id, platform: 'vk',
      test: isTest, media_count: mediaList.length, ...r
    };
    try {
      fs.appendFileSync(LEDGER, JSON.stringify(rec) + '\n');
      return true;
    } catch (le) {
      try {
        log({ id: t.id, platform: 'vk',
          status: 'ledger-append-failed',
          ledger_status: (r && r.status) || null,
          external_id: (r && r.external_id) || null,
          error: scrub((le && le.message) || le).slice(0, 150) });
      } catch (e2) {}
      return false;
    }
  };
  // Orphan probe shared by both response-loss paths (a wall.post
  // transport error and a resolved response without post_id): if the
  // post did land, the newest wall items carry our exact text -
  // recover external_id into the ledger so the operator has the post
  // id instead of a blind "maybe". Best-effort; a probe failure
  // leaves maybe_live only.
  const probeOrphan = async () => {
    try {
      // count=20, not 5: the date >= winStart filter below is what
      // bounds misattribution (~10min), so a wider fetch only widens
      // the NET - on a busy wall more than 5 posts can land inside
      // the probe window and push the orphaned post past the reach of
      // a count=5 scan. Still bounded: one page, no pagination.
      const got = await vkCall('wall.get',
        'owner_id=' + encodeURIComponent(owner) + '&count=20');
      // Exact-text match alone can attribute the WRONG post: if the
      // same text was published earlier (a re-approve of an
      // identical draft, a repost), the probe would record the old
      // post's id and the 'delete manually' note would point the
      // operator at it. Bound the match: the post must sit on OUR
      // wall (owner_id equals VK_USER_ID - a user wall can also
      // carry posts by others) AND be authored by us: authorship
      // lives in from_id, not owner_id - a third party's post on the
      // operator's wall carries the operator's owner_id too, so a
      // same-text post by someone else inside the window would be
      // misattributed as the orphaned wall.post. And be no older
      // than 10min - the failed wall.post either just landed or
      // never will, so a same-text post outside the window is a
      // different post. Newest match first.
      const winStart = Math.floor(Date.now() / 1000) - 600;
      // Normalized-prefix text match, not exact equality: VK can
      // rewrite the stored text (whitespace runs collapsed, a tail
      // link folded into an attachment), and exact equality then
      // misses a post that DID land - the file degrades to maybe_live
      // with no external_id while an orphan post stays on the wall.
      // A wall item qualifies when its normalized text starts with
      // our normalized 80-char head (covers whitespace tweaks and an
      // appended tail) OR is itself a >=40-char prefix of our
      // normalized text (covers a folded-away tail); the 40-char
      // floor keeps a nearly-empty fold from matching a different
      // post. Owner+from_id+window bounds above are unchanged.
      const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim();
      const want = norm(t.text);
      const key = want.slice(0, 80);
      const hit = ((got && got.items) || [])
        .filter((it) => {
          const itn = norm(it.text);
          return key !== '' &&
            (itn.startsWith(key) ||
             (itn.length >= 40 && want.startsWith(itn))) &&
            String(it.owner_id) === String(owner) &&
            String(it.from_id) === String(owner) &&
            Number(it.date || 0) >= winStart;
        })
        .sort((a, b) => Number(b.date || 0) - Number(a.date || 0))[0];
      return (hit && hit.id) ? owner + '_' + hit.id : null;
    } catch (e) { return null; }
  };
  // dry-run (issue #36): exercise claim -> media resolve -> param
  // build with ZERO VK calls - a CI/smoke path that runs the driver
  // end-to-end without a real wall.post. Strict boolean like `test`;
  // both spellings accepted. The mock returns before the token check
  // and upload too, so it never touches the host service or VK at
  // all - a dry-run works even with the token service down.
  if (t.dry_run === true || t.mock === true) {
    const mres = mediaList.map((orig) => resolveMedia(orig));
    const mok = mres.filter(Boolean).length;
    ledger({ status: 'dry-run', note: 'mock publish - no VK calls',
      text_len: String(t.text || '').length,
      media_resolved: mok, media_failed: mediaList.length - mok });
    vkStatus('ok', '', fname);
    return { status: 'dry-run', external_id: null,
      via: 'vk api dry-run (mock - no wall.post, media resolved ' +
        mok + '/' + mediaList.length + ')' };
  }
  if (!vkToken) {
    let ok = false;
    let svcErr = null;
    try { ok = await vkRefresh(); } catch (e) { svcErr = e; }
    if (!ok) {
      // token service down / cannot mint a token - NOT a VK auth
      // rejection, so no vk_code=5: the operator needs to know which
      // side failed (host refresh service vs VK API). A busy
      // (503/retryable) answer is transient lock contention, and an
      // unreachable host (systemd restart, reboot, ECONNREFUSED) is
      // equally transient - wall.post provably never ran on either
      // path (no token -> no VK call at all), so the tick requeues the
      // file bounded by t.retries rather than failing it. Only a
      // classified non-503 service answer (isRetryableRefreshErr -
      // e.g. 502 'token rejected') or a resolved no-token answer stays
      // terminal.
      const busy = isBusyRefreshErr(svcErr);
      const e = new Error(svcErr
        ? (svcErr.state_write
            ? 'vk: token state write failed'
            : 'vk: token service ' + (busy ? 'busy' : 'unreachable')) +
          ': ' + scrub(svcErr).slice(0, 120)
        : 'vk: token service returned no token');
      if (svcErr && svcErr.state_write) {
        // the service minted a token but the state-dir persist threw
        // - a local FS failure, NOT a token-service outage: flag it
        // so the tick reports state_write_error and fails the file
        // terminally. A retryable requeue would hit the same broken
        // dir next tick (the queue sits on the same volume) while
        // misreporting the cause as vk-token.service.
        e.state_write = true;
      } else {
        e.token_service = true;
        if (svcErr && isRetryableRefreshErr(svcErr)) e.retryable = true;
        if (busy) e.busy = true;
      }
      throw e;
    }
  }
  // media upload (issue #36): a Code node cannot send a real
  // multipart body across the task-runner proxy (the TG preview uses
  // a dedicated HTTP node for sendPhoto for the same reason), so
  // each resolved file goes through the host upload endpoint, which
  // reads the same materials dir the n8n mount exposes read-only.
  // The VK token never crosses the container boundary: the service
  // mints it itself; we send only the root-relative path behind the
  // same X-Shared-Token gate /vk-token uses. A per-file failure is
  // non-fatal - the post still publishes with what attached and the
  // drop is reported (same N/M semantics the preview uses).
  const UPLOAD_URL = ENV('VK_UPLOAD_URL') ||
    'http://10.0.2.2:8792/vk-photo-upload';
  const attachments = [];
  const mediaFailed = [];
  for (const orig of mediaList) {
    const resolved = resolveMedia(orig);
    if (!resolved) { mediaFailed.push(orig + ' (unresolvable)'); continue; }
    try {
      // re-canonicalize at use time, same check-then-use escape
      // discipline as the preview's media loop: the rel sent to the
      // host service must name a file under the same mount root the
      // preview resolved - the service repeats the under-root check
      // host-side, but a swapped symlink must not leak the outside
      // path into a request at all
      const real = fs.realpathSync(resolved);
      if (!(real === MEDIA_ROOT_REAL ||
          real.startsWith(MEDIA_ROOT_REAL + '/'))) {
        mediaFailed.push(orig + ' (escaped materials root)');
        continue;
      }
      const rel = real.slice(MEDIA_ROOT_REAL.length + 1);
      const up = await http({
        method: 'POST', url: UPLOAD_URL, json: true,
        // upload can include a host-side token mint (tab reload +
        // poll) plus the multipart itself - 90s matches the refresh
        // budget shape, and a lost upload answer is safe: nothing
        // was posted yet, the file just retries the media step
        timeout: 90000,
        headers: REFRESH_HEADERS,
        body: { rel: rel }
      });
      if (up && up.ok && up.attachment) {
        attachments.push(up.attachment);
      } else if (up && up.retryable) {
        const e = new Error('vk: photo upload transiently failed: ' +
          scrub(up.error || 'retryable answer').slice(0, 150));
        e.retryable = true;
        throw e;
      } else {
        mediaFailed.push(orig + ' (' +
          scrub((up && up.error) || 'upload failed').slice(0, 120) + ')');
      }
    } catch (ue) {
      if (ue && ue.retryable) throw ue;
      // a thrown upload error carrying a 503/retryable shape or no
      // HTTP status at all (unreachable host, timeout, gateway blip)
      // is transient - same classification the token-refresh path
      // uses, and the same safety argument: wall.post has not run,
      // so requeueing the file cannot duplicate anything and the
      // retry re-attempts the media step instead of degrading the
      // post to text-only. A classified non-503 answer (400 bad
      // path, 502 verdict) stays a per-file terminal drop.
      if (isBusyRefreshErr(ue) || !refreshHttpStatus(ue)) {
        const e = new Error('vk: photo upload transiently failed: ' +
          scrub(ue).slice(0, 150));
        e.retryable = true;
        throw e;
      }
      mediaFailed.push(orig + ' (' + scrub(ue).slice(0, 120) + ')');
    }
  }
  // an all-media post must not publish empty: a queue file with no
  // text and nothing attached is a terminal error - the alternative
  // is a bare wall.post of an empty message, which VK rejects or
  // worse, posts blank
  if (!String(t.text || '').trim() && !attachments.length) {
    const e = new Error('vk: no text and no attached media - ' +
      'nothing to publish (' + mediaFailed.length +
      ' media failed: ' + mediaFailed.join('; ').slice(0, 200) + ')');
    throw e;
  }
  let res;
  try {
    res = await vkCall('wall.post',
      'owner_id=' + encodeURIComponent(owner) +
      '&message=' + encodeURIComponent(t.text || '') +
      (attachments.length
        ? '&attachments=' + encodeURIComponent(attachments.join(','))
        : ''));
  } catch (e) {
    // Transport loss after the request was sent is the dangerous case:
    // wall.post may already have landed on VK's side and only the
    // response was lost (timeout/reset) - the file then goes to
    // failed/ with no post-created record and a re-approve would run
    // wall.post AGAIN = a duplicate live post. A definite VK error
    // body (vk_code set) means the call was rejected server-side, so
    // only transport/config failures get the flag.
    if (!e.vk_code && !e.token_service) {
      e.maybe_live = true;
      e.orphan_id = await probeOrphan() || undefined;
      if (e.orphan_id) {
        ledger({ status: 'maybe-live', external_id: e.orphan_id,
          note: 'wall.post response lost; matching text found on wall - ' +
            'treat as published, delete manually if unwanted' });
      }
    }
    throw e;
  }
  const postId = res && res.post_id;
  if (!postId) {
    // A resolved response WITHOUT post_id is the same ambiguity as a
    // lost one: VK answered, but nothing proves the post did NOT
    // land. Flag maybe_live so the failed/ move, the ledger record
    // and the warning text all carry it, and run the same orphan
    // probe the transport-loss path uses.
    const e = new Error('vk: wall.post returned no post_id');
    e.maybe_live = true;
    e.orphan_id = await probeOrphan() || undefined;
    if (e.orphan_id) {
      ledger({ status: 'maybe-live', external_id: e.orphan_id,
        note: 'wall.post response had no post_id; matching text found ' +
          'on wall - treat as published, delete manually if unwanted' });
    }
    throw e;
  }
  const ext = owner + '_' + postId;
  // ledger-first: external_id hits disk the instant wall.post returns,
  // BEFORE the verification call. A verify throw can no longer orphan
  // a live wall post with no recorded id. The append itself can still
  // fail (ENOSPC/EACCES on the state dir): the post IS live and ext
  // already holds its id, so a failed ledger write must not surface
  // as a bare publish_error in failed/ with no maybe_live and no
  // post-created record - exactly the orphan ledger-first ordering
  // exists to prevent. Flag the thrown error maybe_live and carry ext
  // as orphan_id: the failed/ move then writes the 'failed' ledger
  // record with the post id (the append is retried there - a
  // transient failure can land it), the operator line carries
  // 'POST MAY BE LIVE - check VK wall', and ledger()'s publish.jsonl
  // fallback already parked the same evidence in a different dir.
  if (!ledger({ status: 'post-created', external_id: ext })) {
    const e = new Error('vk: publish ledger append failed after ' +
      'wall.post landed - post ' + ext + ' IS LIVE on the wall');
    e.maybe_live = true;
    e.orphan_id = ext;
    throw e;
  }
  // post-publish verification: the post must read back from the wall.
  // A verify failure is recorded and tolerated - the post is live
  // either way and post-created above already holds the evidence.
  let verified = false;
  try {
    const got = await vkCall('wall.getById', 'posts=' + encodeURIComponent(ext));
    verified = !!(got && Array.isArray(got.items) &&
      got.items.length && Number(got.items[0].id) === Number(postId));
  } catch (e) {
    ledger({ status: 'verify-failed', external_id: ext, verified: false,
      verify_error: scrub(e).slice(0, 200) });
  }
  ledger({ status: 'published', external_id: ext,
    verified: verified, deleted: false,
    media_attached: attachments.length,
    media_failed: mediaFailed.length ? mediaFailed : undefined });
  let status = 'published';
  let deleted = false;
  let deleteErr = null;
  // test drafts are published, verified, then deleted from the wall.
  // A delete failure is recorded as a second ledger record
  // (test-delete-failed + delete_error) and does not fail the file:
  // the records above already hold external_id.
  if (isTest) {
    try {
      const del = await vkCall('wall.delete',
        'owner_id=' + encodeURIComponent(owner) +
        '&post_id=' + encodeURIComponent(postId));
      // VK answers response:1 on success - a falsy/0 response means the
      // delete silently did not land even though no error was raised
      if (Number(del) !== 1) {
        throw new Error('wall.delete returned ' +
          scrub(JSON.stringify(del)).slice(0, 100));
      }
      deleted = true;
      status = 'test-published-deleted';
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: true });
    } catch (e) {
      status = 'test-delete-failed';
      deleteErr = scrub(e).slice(0, 200);
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: false, delete_error: deleteErr });
    }
  }
  // 'ok' only on full success: a failed test delete leaves a live test
  // post, an unverifiable post is not a clean publish - each gets its
  // own status instead of a silent 'ok'.
  if (deleteErr) vkStatus('test_delete_failed', deleteErr, fname);
  else if (!verified) vkStatus('publish_unverified', '', fname);
  else vkStatus('ok', '', fname);
  // surface the media outcome in the operator-facing result line
  // too, not only the ledger: the moderation preview reports 'N/M
  // photo(s) attached', so a silent text-only post would look like
  // lost attachments
  // external_id rides the result so the registry event below records
  // the VK post id without re-parsing it out of the `via` string
  return { status: status, external_id: ext, via: 'vk api wall.post ' + ext +
    (verified ? ' verified' : ' UNVERIFIED') +
    (isTest ? (deleted ? ' +deleted' : ' DELETE-FAILED') : '') +
    (mediaList.length ? ' media attached: ' + attachments.length +
      '/' + mediaList.length +
      (mediaFailed.length ? ' (' + mediaFailed.length + ' failed)' : '')
      : '') };
}

// LinkedIn driver (issue #38): personal-profile UGC share, same
// ledger/orphan/test semantics as publishVk. v1 is text-only: image
// attach needs LinkedIn's registerUpload+PUT-binary flow, and a Code
// node cannot push a binary body across the task-runner proxy (the
// same boundary that put VK uploads behind the host service) - media
// entries drop per-file until a host-side LinkedIn upload endpoint
// ships.
async function publishLinkedin(t, fname) {
  if (!LI_AUTHOR) throw new Error('linkedin: LINKEDIN_PERSON_URN not set');
  const isTest = t.test === true;
  const mediaList = (Array.isArray(t.media) ? t.media : [])
    .concat(t.image ? [t.image] : []);
  // same never-throws ledger contract as publishVk - the fallback
  // line into publish.jsonl keeps an external id on disk even when
  // the state dir itself is broken
  const ledger = (r) => {
    const rec = {
      ts: new Date().toISOString(), id: t.id, platform: 'linkedin',
      test: isTest, media_count: mediaList.length, ...r
    };
    try {
      fs.appendFileSync(LEDGER, JSON.stringify(rec) + '\n');
      return true;
    } catch (le) {
      try {
        log({ id: t.id, platform: 'linkedin',
          status: 'ledger-append-failed',
          ledger_status: (r && r.status) || null,
          external_id: (r && r.external_id) || null,
          error: scrub((le && le.message) || le).slice(0, 150) });
      } catch (e2) {}
      return false;
    }
  };
  // orphan probe: own UGC posts, normalized-prefix text match bounded
  // by author + 10min window - same attribution rules as the VK probe
  const probeOrphan = async () => {
    try {
      const got = await liCall('GET',
        '/v2/ugcPosts?q=authors&authors=List(' +
        encodeURIComponent(LI_AUTHOR) + ')&count=20&sortBy=LAST_MODIFIED');
      const winStart = Date.now() - 600 * 1000;
      const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim();
      const want = norm(t.text);
      const key = want.slice(0, 80);
      const hit = ((got && got.elements) || [])
        .filter((it) => {
          const sc = (it.specificContent || {})[
            'com.linkedin.ugc.ShareContent'] || {};
          const itn = norm((sc.shareCommentary || {}).text);
          const created = Number((it.created || {}).time || 0);
          return key !== '' &&
            (itn.startsWith(key) ||
             (itn.length >= 40 && want.startsWith(itn))) &&
            String(it.author || '') === LI_AUTHOR &&
            created >= winStart;
        })
        .sort((a, b) => Number((b.created || {}).time || 0) -
          Number((a.created || {}).time || 0))[0];
      return (hit && hit.id) ? String(hit.id) : null;
    } catch (e) { return null; }
  };
  // dry-run: claim -> media accounting -> param build, zero LinkedIn
  // calls and no token requirement - same contract as the VK mock
  if (t.dry_run === true || t.mock === true) {
    ledger({ status: 'dry-run', note: 'mock publish - no LinkedIn calls',
      text_len: String(t.text || '').length,
      media_dropped: mediaList.length });
    liStatus('ok', '', fname);
    return { status: 'dry-run', external_id: null,
      via: 'linkedin api dry-run (mock - no ugcPosts, media ' +
        mediaList.length + ' unsupported)' };
  }
  if (!LI_TOKEN) {
    throw new Error('linkedin: LINKEDIN_ACCESS_TOKEN not set - ' +
      'run the browser OAuth re-issue flow');
  }
  // media unsupported in v1: every entry drops per-file; a post
  // with no text AND no attached media must not go out empty
  const mediaFailed = mediaList.map((orig) =>
    orig + ' (media unsupported - linkedin v1)');
  if (!String(t.text || '').trim()) {
    throw new Error('linkedin: no text and media unsupported in v1 - ' +
      'nothing to publish (' + mediaList.length + ' media dropped)');
  }
  const postBody = {
    author: LI_AUTHOR,
    lifecycleState: 'PUBLISHED',
    specificContent: {
      'com.linkedin.ugc.ShareContent': {
        shareCommentary: { text: String(t.text) },
        shareMediaCategory: 'NONE'
      }
    },
    visibility: {
      'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC'
    }
  };
  let res;
  try {
    res = await liCall('POST', '/v2/ugcPosts', postBody);
  } catch (e) {
    // a thrown error without an HTTP status is the dangerous case:
    // ugcPosts may already have landed and only the response was lost
    // (timeout/reset). A definite LinkedIn answer (li_status set -
    // includes 401/403 auth rejections and the transient-status
    // family) proves the post never ran, so only transport/config
    // failures get the flag - same rule as the VK wall.post catch.
    if (!e.li_status && !e.li_auth) {
      e.maybe_live = true;
      e.orphan_id = await probeOrphan() || undefined;
      if (e.orphan_id) {
        ledger({ status: 'maybe-live', external_id: e.orphan_id,
          note: 'ugcPosts response lost; matching text found - ' +
            'treat as published, delete manually if unwanted' });
      }
    }
    throw e;
  }
  // UGC create returns the entity URN in the x-restli-id header and
  // typically an {id} body field; helpers.httpRequest gives us the
  // body only, so an answer without id falls into the same ambiguous
  // branch as a lost response - the orphan probe recovers the URN.
  const postId = res && (res.id || res['x-restli-id']);
  if (!postId) {
    const e = new Error('linkedin: ugcPosts returned no post id');
    e.maybe_live = true;
    e.orphan_id = await probeOrphan() || undefined;
    if (e.orphan_id) {
      ledger({ status: 'maybe-live', external_id: e.orphan_id,
        note: 'ugcPosts response had no id; matching text found - ' +
          'treat as published, delete manually if unwanted' });
    }
    throw e;
  }
  const ext = String(postId);
  // ledger-first like VK: the share URN hits disk before any verify
  // call so a later throw cannot orphan a live post without a
  // durable id; a failed append flags maybe_live with ext as
  // orphan_id instead of surfacing a bare publish_error
  if (!ledger({ status: 'post-created', external_id: ext })) {
    const e = new Error('linkedin: publish ledger append failed ' +
      'after ugcPosts landed - post ' + ext + ' IS LIVE');
    e.maybe_live = true;
    e.orphan_id = ext;
    throw e;
  }
  let verified = false;
  try {
    const got = await liCall('GET',
      '/v2/ugcPosts/' + encodeURIComponent(ext));
    verified = !!(got && (got.id === ext ||
      String(got.id || '') === ext));
  } catch (e) {
    ledger({ status: 'verify-failed', external_id: ext,
      verified: false, verify_error: scrub(e).slice(0, 200) });
  }
  ledger({ status: 'published', external_id: ext,
    verified: verified, deleted: false,
    media_attached: 0,
    media_failed: mediaFailed.length ? mediaFailed : undefined });
  let status = 'published';
  let deleted = false;
  let deleteErr = null;
  if (isTest) {
    try {
      // DELETE /v2/ugcPosts/{urn}: the URN itself is the path segment
      // and must be URL-encoded (it contains colons); a 2xx/204 is
      // the only success proof - LinkedIn returns an empty body
      await liCall('DELETE',
        '/v2/ugcPosts/' + encodeURIComponent(ext));
      deleted = true;
      status = 'test-published-deleted';
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: true });
    } catch (e) {
      status = 'test-delete-failed';
      deleteErr = scrub(e).slice(0, 200);
      ledger({ status: status, external_id: ext,
        verified: verified, deleted: false, delete_error: deleteErr });
    }
  }
  if (deleteErr) liStatus('test_delete_failed', deleteErr, fname);
  else if (!verified) liStatus('publish_unverified', '', fname);
  else liStatus('ok', '', fname);
  return { status: status, external_id: ext,
    via: 'linkedin api ugcPosts ' + ext +
      (verified ? ' verified' : ' UNVERIFIED') +
      (isTest ? (deleted ? ' +deleted' : ' DELETE-FAILED') : '') +
      (mediaList.length ? ' media dropped: ' + mediaList.length +
        ' (unsupported)' : '') };
}

const out = [];

// housekeeping: files parked as *.stale-<ts> on claim and orphaned
// dot-tmp payloads accumulate forever otherwise - prune anything
// older than 24h once per tick
try {
  const cutoff = Date.now() - 24 * 3600 * 1000;
  for (const f of fs.readdirSync(Q + '/processing')) {
    // also sweep orphaned .<id>.tmp-* payloads: the approve-sync
    // write in sp-tg-moderation (Handle TG Update) stages its
    // dot-tmp inside processing/ before the atomic rename, so a
    // crash there strands it - the *.json claim pass below never
    // sees dot files
    if (!f.includes('.stale-') && !f.startsWith('.')) continue;
    try {
      const p = Q + '/processing/' + f;
      // ctimeMs, not mtimeMs: a *.stale-* file lands here via mv()'s
      // link()+unlink()/rename, which bumps ctime while mtime keeps
      // the original enqueue write time - a claim parked after a
      // long queue wait would otherwise prune almost immediately.
      // Orphaned dot-tmp files are created fresh (ctime ~ mtime),
      // so the same clock is right for both.
      if (fs.statSync(p).ctimeMs < cutoff) {
        fs.unlinkSync(p);
        log({ file: f, status: 'stale-pruned' });
      }
    } catch (e) {}
  }
  for (const f of fs.readdirSync(Q)) {
    if (!f.startsWith('.')) continue;
    try {
      const p = Q + '/' + f;
      if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
    } catch (e) {}
  }
  // orphaned writeJsonAtomic staging files in the state dir: a crash
  // between write and rename strands vk_token.json.tmp-* /
  // vk_status.json.tmp-* forever. Match the actual staging suffixes:
  // '.tmp-' (current unique names) plus the exact '.tmp' tail of
  // pre-unique-name leftovers - a bare '.tmp' substring match would
  // also unlink unrelated names like 'x.tmplate' or 'notes.tmpx'
  for (const f of fs.readdirSync(STATE)) {
    if (f.indexOf('.tmp-') === -1 && !f.endsWith('.tmp')) continue;
    try {
      const p = STATE + '/' + f;
      if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
    } catch (e) {}
  }
  // same orphan pattern one level down in state/drafts/: Prepare
  // Draft and saveDraft stage '<id>.json.tmp-*' there, and a crash
  // between write and rename strands them - no reader ever touches
  // them again. Same tightened '.tmp-'/'.tmp'-tail match as the STATE
  // sweep above: drafts are user-visible names, so a broad '.tmp'
  // substring could unlink a real draft file
  try {
    for (const f of fs.readdirSync(STATE + '/drafts')) {
      if (f.indexOf('.tmp-') === -1 && !f.endsWith('.tmp')) continue;
      try {
        const p = STATE + '/drafts/' + f;
        if (fs.statSync(p).mtimeMs < cutoff) fs.unlinkSync(p);
      } catch (e) {}
    }
  } catch (e) { /* drafts dir absent - nothing to sweep */ }
  // stale-draft GC: drafts stuck in 'pending' (preview delivered,
  // never decided) or 'delivering' (preview send never confirmed)
  // wedge their draft_id behind Prepare Draft's overwrite guard and
  // leave live Approve buttons on old TG previews - a tap on one
  // silently republishes week-old text. Anything older than
  // STALE_DRAFT_MS (default 7d) is auto-rejected - 'rejected' is
  // REWRITABLE so the id frees up - and its preview keyboard is
  // disarmed so no stale tap survives.
  const staleCutoff = Date.now() - Math.max(0,
    parseInt(ENV('STALE_DRAFT_MS') || '', 10) || 7 * 24 * 3600 * 1000);
  let staleFiles = null;
  try { staleFiles = fs.readdirSync(STATE + '/drafts'); }
  catch (e) { /* drafts dir absent - nothing to sweep */ }
  try {
  if (staleFiles) for (const f of staleFiles) {
    if (!f.endsWith('.json') || f.startsWith('.')) continue;
    const p = STATE + '/drafts/' + f;
    let d = null;
    try { d = JSON.parse(fs.readFileSync(p, 'utf8')); }
    catch (e) { continue; }
    if (!d || (d.status !== 'pending' && d.status !== 'delivering')) continue;
    const created = Date.parse(d.created_at || '');
    if (!(created > 0) || created > staleCutoff) continue;
    // disarm the preview keyboard before flipping status:
    // 'pending' is the only state with a confirmed live preview
    // (message_id persisted with it); 'delivering' never got one.
    // A strip failure must not hold the GC - the file is still
    // rejected below and the leftover button only revives on an
    // informed tap, same as any rejected draft's preview.
    if (d.status === 'pending' && d.message_id && chatId) {
      try {
        await tg('editMessageReplyMarkup', {
          chat_id: chatId, message_id: d.message_id,
          reply_markup: { inline_keyboard: [] } });
      } catch (e) {
        log({ draft: d.id, status: 'stale_kb_strip_failed' });
      }
    }
    // re-read before write AND pin identity, not just status:
    // 'delivering' is REWRITABLE in Prepare Draft's guard, so in
    // the window between our scan and this write the same
    // draft_id may already hold a FRESH draft (stale 'pending'
    // -> 'rejected' -> new 'delivering'). Status alone cannot
    // tell those apart - same discipline as updateDraft/
    // sameDraftSnapshot: pin status + created_at.
    try {
      const cur = JSON.parse(fs.readFileSync(p, 'utf8'));
      if (!cur || cur.status !== d.status ||
          cur.created_at !== d.created_at) continue;
      cur.status = 'rejected';
      cur.stale_rejected_at = new Date().toISOString();
      writeJsonAtomic(p, cur);
    } catch (e) {
      log({ draft: d.id, status: 'stale_reject_write_failed',
        error: String(e && e.message || e) });
      continue;
    }
    log({ draft: d.id, status: 'stale_rejected',
      age_ms: Date.now() - created });
    // registry: the auto-reject is a real moderation-stage terminal
    // transition - without it the service would sit at
    // draft/pending forever. Pre-registry drafts carry no post_id
    // and are skipped by the helper itself.
    registryEvent({ post_id: d.post_id, draft_id: d.id,
      platform: d.platform, stage: 'moderation', status: 'rejected',
      writer: 'sp-publish',
      error: 'stale draft auto-rejected' });
    out.push(d.id + ' stale draft auto-rejected (' +
      Math.round((Date.now() - created) / 3600000) + 'h old)');
  }
  } catch (e) {
    // a sweep fault must not abort the remaining housekeeping
    // passes - log it and let terminal-prune / rotation run
    log({ status: 'stale_draft_sweep_error',
      error: String(e && e.message || e) });
  }
  // terminal dirs grow unbounded - drop queue records older than 30
  // days once per tick. publish.jsonl + published.jsonl keep the
  // audit trail, so the payload file itself is not needed that long.
  // ctimeMs, not mtimeMs: the terminal copy lands via mv()'s
  // link()+unlink() (or the rename fallback), which bumps ctime while
  // mtime keeps the original enqueue write time - mtime would prune a
  // file that sat in the queue for weeks days after it completed,
  // instead of 30 days after the terminal move.
  const termCutoff = Date.now() - 30 * 24 * 3600 * 1000;
  for (const dir of ['done', 'failed', 'skipped']) {
    let pruned = 0;
    for (const f of fs.readdirSync(Q + '/' + dir)) {
      try {
        const p = Q + '/' + dir + '/' + f;
        if (fs.statSync(p).ctimeMs < termCutoff) {
          fs.unlinkSync(p);
          pruned++;
        }
      } catch (e) {}
    }
    if (pruned) log({ status: 'terminal-pruned', dir: dir, count: pruned });
  }
  // size-based log rotation: the jsonl logs grow forever otherwise
  // (the terminal queues above already prune at 30d). Over 5MB the
  // live file is renamed aside to <name>.1 - a single generation, a
  // previous .1 is replaced - and the next append starts a fresh
  // file. Renames are atomic and every writer appends by path, so a
  // mid-rotation append cannot be lost. state/published.jsonl stays
  // OUT of this on purpose: it is the append-only durable publish
  // evidence that publishedIds() in sp-tg-moderation indexes, and
  // truncating it would re-open duplicate wall.posts.
  const rotateIfBig = (p) => {
    try {
      if (fs.statSync(p).size > 5 * 1024 * 1024) {
        fs.renameSync(p, p + '.1');
        log({ file: p, status: 'log-rotated' });
      }
    } catch (e) {}
  };
  for (const lf of [LOGD + '/moderation.jsonl', LOGD + '/publish.jsonl',
    LOGD + '/content-gen.jsonl']) {
    rotateIfBig(lf);
  }
} catch (e) {}

// terminal moves: a failed rename (file removed externally, ENOSPC)
// must not abort the whole tick mid-loop - remaining queue files
// still need processing, so every move below goes through mv()
const mv = (from, to, what) => {
  // unique collision-park name; ms-resolution timestamp alone is not
  // unique enough - two collision-park moves of the same <id>.json
  // inside one millisecond would still collide, so add a random
  // component
  const park = () => to + '.mv-' + Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 6);
  // label the log fields by meaning, not by parameter name: `from`
  // stays the source, intended_to the requested name, parked_as the
  // collision-parked one
  const logParked = (dest) => log({ file: what || from,
    status: 'move-renamed', from: from, intended_to: to,
    parked_as: dest });
  try {
    // link(2)+unlink(2), NOT existsSync+rename: rename(2) silently
    // replaces a same-name destination, so a file parked between the
    // check and the call (a second tick's terminal move of the same
    // <id>.json - A's crashed-claim recovery vs B's fresh claim of a
    // requeue) would be clobbered outright. link() fails EEXIST
    // instead - the same primitive the enqueue path in Handle TG
    // Update and the retry hand-back below already use - and the
    // incoming file is then parked under a unique suffix. Probes
    // only ever look for the bare <id>.json name, so the original
    // record still answers them (the ledger keeps the audit trail).
    let dest = to;
    try {
      fs.linkSync(from, dest);
    } catch (le) {
      if (le && le.code === 'EEXIST') {
        // name taken - before the move or inside the check-to-move
        // gap this primitive exists to close: park, never overwrite
        dest = park();
        try {
          fs.linkSync(from, dest);
        } catch (le2) {
          if (!(le2 && le2.code === 'EEXIST')) throw le2;
          dest = park();
          // a third EEXIST (or any other error) -> move-failed below
          fs.linkSync(from, dest);
        }
        logParked(dest);
      } else if (le && (le.code === 'EXDEV' || le.code === 'EPERM' ||
          le.code === 'ENOSYS')) {
        // hardlinks need source and destination on one filesystem
        // with link support - every move here stays inside Q/, but a
        // re-mounted or relocated queue must keep working: fall back
        // to the rename path with its existsSync guard (the clobber
        // window returns only where link(2) is not feasible)
        dest = to;
        if (fs.existsSync(dest)) dest = park();
        fs.renameSync(from, dest);
        // log AFTER the rename lands, same ordering as the EEXIST
        // branch above: logging 'move-renamed' before renameSync
        // would record a false park when the rename itself throws
        // (a 'move-renamed' line immediately followed by
        // 'move-failed' for one move)
        if (dest !== to) logParked(dest);
        return true;
      } else {
        throw le;
      }
    }
    try {
      fs.unlinkSync(from);
    } catch (ue) {
      // the link already landed - dest is valid, only the source
      // name is left behind. In processing/ a leftover claim is
      // reclaimed to failed/ by the stuck-claim pass; still log it -
      // a silent duplicate would read as a second copy
      log({ file: what || from, status: 'move-src-leftover',
        from: from, to: dest, error: String(ue).slice(0, 120) });
    }
    return true;
  } catch (e) {
    log({ file: what || from, status: 'move-failed',
      from: from, to: to,
      error: String(e).slice(0, 150) });
    return false;
  }
};

// stuck-claim recovery: a plain *.json file left in processing/ means
// a tick died between the atomic claim rename and the terminal move
// (container restart, ENOSPC on mv). The root readdir below never
// sees it and every Approve keeps answering 'already queued' - the
// draft is blocked forever without this pass. Reclaim anything
// claimed more than 10min ago. ctimeMs - not mtime - is the claim
// timestamp: rename() bumps ctime while mtime keeps the original
// enqueue time, so a long-waiting queue file is not mistaken for a
// stuck claim, and 10min >> the 2min tick plus worst-case publish
// latency. Auto-retry is unsafe (wall.post may already have landed),
// so the file goes to failed/ with a ledger note; the operator
// checks the wall and re-approves through the normal requeue path.
try {
  const stuckCutoff = Date.now() - 10 * 60 * 1000;
  for (const f of fs.readdirSync(Q + '/processing')) {
    // *.stale-* files are pruned by the housekeeping pass above;
    // only a live claim ends in .json
    if (!f.endsWith('.json')) continue;
    const p = Q + '/processing/' + f;
    let st = null;
    try { st = fs.statSync(p); } catch (e) { continue; }
    if (st.ctimeMs > stuckCutoff) continue;
    let pid = null;
    let pplat = null;
    let ppost = null;
    try {
      const pj = JSON.parse(fs.readFileSync(p, 'utf8'));
      pid = pj.id || null;
      pplat = pj.platform || null;
      ppost = pj.post_id || null;
    } catch (e) {}
    if (!mv(p, Q + '/failed/' + f, f)) continue;
    const note = 'tick died between claim and terminal move - ' +
      'post may be live, check the VK wall before re-approving';
    log({ file: f, id: pid, platform: pplat,
      status: 'stuck-claim-recovered', note: note });
    // registry: the park in failed/ is a terminal publish failure
    // with maybe_live - without the event the service would sit at
    // moderation/approved forever
    registryEvent({ post_id: ppost, draft_id: pid, platform: pplat,
      stage: 'publish', status: 'failed', writer: 'sp-publish',
      maybe_live: true,
      error: 'stuck claim recovered - post may be live' });
    try {
      fs.appendFileSync(LEDGER, JSON.stringify({
        ts: new Date().toISOString(), id: pid, platform: pplat,
        file: f, status: 'stuck-claim-recovered', maybe_live: true,
        note: note
      }) + '\n');
    } catch (e) {}
    // same reporting discipline as every other terminal move in this
    // node: a recovery parks the file in failed/ (a real, maybe-live
    // failure), so vk_status.json must reflect it now - without this
    // write the status file keeps the PREVIOUS tick's headline and
    // the recovered file only surfaces at the next driver event.
    // Underscore name like the rest of the vkStatus vocabulary; the
    // reason carries the maybe-live note so the status headline says
    // why the wall needs a manual check.
    (canonPlat(pplat) === 'linkedin' ? liStatus : vkStatus)(
      'stuck_claim_recovered', note, f);
    out.push(f + ' recovered from stuck claim -> failed/ (post may be live)');
  }
} catch (e) {}
// existsSync+readdirSync is a TOCTOU and the one unguarded FS read
// in this node - a transient FS error would abort the whole tick.
// A failed scan degrades to an empty list; the next tick retries.
let files = [];
try { files = fs.readdirSync(Q).filter(f => f.endsWith('.json')); }
catch (e) { log({ status: 'queue_scan_failed', error: String(e && e.message || e) }); }
for (const f of files) {
  // claim the queue file atomically BEFORE any await: rename into
  // processing/. When two ticks overlap, the second one sees the file
  // gone (rename throws) and skips it - no double wall.post.
  const claimed = Q + '/processing/' + f;
  try {
    // a same-name file in processing/ is either a LIVE claim from a
    // concurrent tick mid-wall.post or a crashed claim's leftover -
    // and any *.json left here is younger than the 10min stuck window
    // by construction (the recovery pass above already reclaimed the
    // older ones). Moving a live claim aside breaks mutual exclusion:
    // the owner tick keeps publishing while this tick would rename
    // the queue file over the orphaned slot and wall.post it AGAIN.
    // Check the claim age first (ctimeMs - rename bumps ctime, same
    // clock the stuck-recovery pass uses): younger than the stuck
    // threshold means another tick owns it - SKIP the queue file and
    // leave the claim untouched; a later tick retries after the
    // owner resolves it. Only park the file as .stale-* once it is
    // past the threshold (a claim that slipped in between the
    // recovery pass and this loop, or whose recovery move failed).
    if (fs.existsSync(claimed)) {
      let cst = null;
      try { cst = fs.statSync(claimed); } catch (e) {}
      // cannot prove the claim is dead -> treat it as live and skip:
      // racing a rename over an active claim is the bug this guard
      // exists to prevent. The queue file stays put for a later tick.
      if (!cst || cst.ctimeMs > Date.now() - 10 * 60 * 1000) {
        log({ file: f,
          status: cst ? 'claim-skip-live' : 'claim-skip-unstattable' });
        continue;
      }
      // mv() already logged 'move-failed' on a miss - recording
      // 'stale-claim-aside' anyway would claim a move that never
      // happened, and the rename below would then clobber the
      // still-parked stale claim outright, destroying the crashed
      // claim's payload (the only local copy of what the dead tick
      // was doing). Skip this queue file instead - the aside-move
      // retries on a later tick, same as the live-claim branch.
      if (!mv(claimed, claimed + '.stale-' + Date.now(), f)) continue;
      log({ file: f, status: 'stale-claim-aside' });
    }
    fs.renameSync(Q + '/' + f, claimed);
  } catch (e) {
    // the expected failure here is rename contention with a
    // concurrent tick - ENOENT (the other tick claimed the
    // source first) or the EBUSY/EEXIST/ENOTEMPTY platform
    // variants of the same race: skip quietly. Anything else is
    // a persistent FS problem (EACCES on processing/, ENOSPC, a
    // wedged bind mount) that would skip this same queue file on
    // every tick forever, so it must leave a log line.
    const code = e && e.code;
    if (code !== 'ENOENT' && code !== 'EBUSY' &&
        code !== 'EEXIST' && code !== 'ENOTEMPTY') {
      log({ file: f, status: 'claim-failed',
        error: scrub(String((e && e.message) || e)).slice(0, 150) });
    }
    continue; // another tick already owns this file
  }
  let t;
  try {
    const parsed = JSON.parse(fs.readFileSync(claimed, 'utf8'));
    // valid JSON is not necessarily a queue payload: null, 42, 'x'
    // or [] all parse fine, then t.platform below throws TypeError
    // OUTSIDE this try - the tick aborts mid-loop, the claim sits in
    // processing/ until the ~10min stuck-claim recovery, and every
    // file queued after it is deferred a tick. Only a plain object
    // is a usable payload; anything else is 'bad json' here.
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error('queue payload is not an object');
    }
    t = parsed;
  } catch (e) {
    mv(claimed, Q + '/failed/' + f, f);
    log({ file: f, status: 'failed', error: 'bad json' });
    // same reporting discipline as the skipped branches below: a tick
    // whose only file is corrupt must not leave the previous
    // headline standing - a stale 'ok' (or a stale auth_error) would
    // read as the current state
    vkStatus('bad_json', 'queue file is not a valid payload object', f);
    out.push(f + ' FAILED: bad json');
    continue;
  }
  const p = canonPlat(String(t.platform || '').toLowerCase());
  if (!ENABLED[p]) {
    mv(claimed, Q + '/skipped/' + f, f);
    log({ id: t.id, platform: t.platform, status: 'skipped', reason: 'platform not enabled' });
    // registry: without the skipped event a disabled-platform service
    // would sit at draft/pending forever
    registryEvent({ post_id: t.post_id, draft_id: t.id, platform: p,
      stage: 'publish', status: 'skipped',
      error: 'platform disabled', writer: 'sp-publish' });
    // vk_status.json is only written on the VK driver paths - a tick
    // whose every file lands here would leave the PREVIOUS tick's
    // status up forever, and a stale 'ok' (or worse, a stale
    // auth_error) reads as the current state. Record the skip so the
    // status file reflects this tick's outcome; 'skipped' ranks below
    // 'ok' in the end-of-tick merge, so it only becomes the headline
    // when the driver never ran at all.
    (p === 'linkedin' ? liStatus : vkStatus)(
      'skipped', 'platform ' + (t.platform || '?') +
      ' not enabled', f);
    out.push((t.id || f) + ' ' + (t.platform || '?') + ' skipped (not enabled)');
    continue;
  }
  // an enabled platform with no driver (PUBLISH_PLATFORMS=all turns
  // on fb, whose driver is not shipped yet) passed the
  // Approve-side ENABLED gate and then used to park in failed/
  // forever on 'no driver for platform' - a terminal outcome for a
  // config-only gap. Park it in skipped/ like the not-enabled case;
  // a shipped driver plus a re-Approve revives it.
  if (p !== 'vk' && p !== 'linkedin') {
    mv(claimed, Q + '/skipped/' + f, f);
    log({ id: t.id, platform: t.platform, status: 'skipped',
      reason: 'no driver for platform ' + p });
    registryEvent({ post_id: t.post_id, draft_id: t.id, platform: p,
      stage: 'publish', status: 'skipped',
      error: 'platform disabled: no driver for ' + p,
      writer: 'sp-publish' });
    (p === 'linkedin' ? liStatus : vkStatus)(
      'skipped', 'no driver for platform ' + p, f);
    out.push((t.id || f) + ' ' + (t.platform || '?') +
      ' skipped (no driver for platform ' + p + ')');
    continue;
  }
  try {
    const r = p === 'linkedin'
      ? await publishLinkedin(t, f)
      : await publishVk(t, f);
    mv(claimed, Q + '/done/' + f, f);
    // status mirrors the ledger: published / test-published-deleted /
    // test-delete-failed - not a flat 'published' for test drafts
    log({ id: t.id, platform: t.platform, via: r.via, status: r.status });
    // registry: 'test-deleted' is its own status in the design (a
    // self-cleaning test post); 'test-delete-failed' means the post
    // is LIVE on the wall, so it folds as published with the delete
    // error attached
    // 'dry-run' keeps its own status - a mock publish must not fold
    // as 'published' (analytics would try to read metrics for a post
    // that never existed) and gets no published_at for the same
    // reason; the ledger carries the dry-run evidence record
    registryEvent({ post_id: t.post_id, draft_id: t.id, platform: p,
      stage: 'publish',
      status: r.status === 'test-published-deleted' ? 'test-deleted'
        : r.status === 'dry-run' ? 'dry-run' : 'published',
      writer: 'sp-publish',
      external_ids: r.external_id ? [r.external_id] : undefined,
      published_at: r.status === 'dry-run'
        ? undefined : new Date().toISOString(),
      error: r.status === 'test-delete-failed'
        ? 'test delete failed - post left live' : undefined });
    out.push((t.id || f) + ' ' + t.platform + ' -> ' + r.via +
      (t.post_id ? ' ' + t.post_id : ''));
  } catch (e) {
    const errStr = scrub(e).slice(0, 300);
    // bound on retryable requeues: e.retryable marks transient
    // failures where wall.post provably never ran - busy lock
    // contention or an unreachable host service (see
    // isRetryableRefreshErr and the throw sites) and the
    // TRANSIENT_VK_CODES family (a definite VK error body means the
    // call was rejected before anything posted), so the claim can
    // safely return to the queue root. But a host reboot or a wedged
    // vk-token.service can keep the error retryable for hours, and an
    // unbounded requeue would cycle claim -> requeue forever (plus a
    // tick report line every 2min). The queue payload carries the
    // count: bump t.retries and persist it on the claim inode BEFORE
    // the link() hand-back - link() shares the inode, so the requeued
    // root file keeps the running total across ticks. Past RETRY_MAX
    // the error falls through to the permanent failed/ move with an
    // explicit reason. A fresh re-Approve rebuilds the payload
    // without `retries` (the enqueue path in Handle TG Update) - an
    // explicit operator retry, so resetting the bound is intended.
    // The payload-sync paths there carry the counter through instead:
    // overwriting an existing queue file is a sync, not a new budget.
    const RETRY_MAX = 5;
    const prevTries = Number(t.retries);
    const tries =
      (Number.isFinite(prevTries) && prevTries > 0
        ? Math.floor(prevTries) : 0) + 1;
    const exhausted = !!(e && e.retryable) && tries > RETRY_MAX;
    if (e && e.retryable && !exhausted) {
      let persisted = false;
      try {
        t.retries = tries;
        // dot-tmp + rename like every other queue write: a torn
        // counter write must not reach the requeued file, and the dot
        // prefix puts a crash-orphaned staging file under the 24h
        // sweep of processing/ dot files above
        const rtmp = Q + '/processing/.' + f + '.rt-' +
          Date.now().toString(36) + '-' +
          Math.random().toString(36).slice(2, 6);
        fs.writeFileSync(rtmp, JSON.stringify(t, null, 2));
        fs.renameSync(rtmp, claimed);
        persisted = true;
      } catch (we) {
        log({ file: f, status: 'retry-counter-write-failed',
          error: String(we).slice(0, 120) });
      }
      if (persisted) {
        // transient token-service answer (busy 503 or
        // unreachable - see isRetryableRefreshErr) or a transient VK
        // rejection (TRANSIENT_VK_CODES). This is NOT a publish failure:
        // return the claim to the queue root so the NEXT tick retries
        // the file. failed/ is for terminal outcomes only - a
        // momentary outage must not permanently burn a publish.
        let note;
        try {
          // atomic exclusive hand-back - the same link(2) discipline
          // the enqueue path in Handle TG Update uses: link() fails
          // EEXIST instead of clobbering, so a fresh (edited) enqueue
          // landing between our publish attempt and this requeue is
          // never overwritten by the stale claim. The
          // existsSync+rename pair this replaced had a micro-TOCTOU:
          // rename() silently replaces a same-name destination, so a
          // concurrent link() enqueue in the gap lost its payload.
          fs.linkSync(claimed, Q + '/' + f);
        } catch (e2) {
          if (e2 && e2.code === 'EEXIST') {
            // a concurrent enqueue already re-created the root file -
            // this stale claim is a duplicate of the same draft:
            // drop it
            try { fs.unlinkSync(claimed); } catch (e3) {}
            note = 'retry: fresh queue file already exists - stale claim dropped';
          } else {
            // could not hand it back - leave the claim in
            // processing/; the ~10min stuck-claim pass reclaims it to
            // failed/ if it wedges
            note = 'retry move failed: ' + String(e2).slice(0, 120);
          }
        }
        if (!note) {
          // the link landed - the root now shares the claim's inode,
          // so drop the processing/ name to leave exactly one copy.
          // An unlink failure is not a requeue failure: the root file
          // publishes normally next tick and the leftover claim is
          // reclaimed to failed/ by the stuck-claim pass.
          try {
            fs.unlinkSync(claimed);
            note = 'retry: ' + (e.vk_transient
              ? 'transient vk error ' + e.vk_code
              : (e.li_status
                ? 'transient linkedin api error ' + e.li_status
                : 'token service ' + (e.busy ? 'busy' : 'down'))) +
              ' - requeued for next tick';
          } catch (e3) {
            note = 'retry: requeued but claim copy left in processing/: ' +
              String(e3).slice(0, 100);
          }
        }
        const reason = (errStr + ' | ' + note).slice(0, 240);
        (p === 'linkedin' ? liStatus : vkStatus)(
          e.vk_transient ? 'vk_transient' :
            (e.li_status ? 'api_transient' :
              (e.busy ? 'token_service_busy' : 'token_service_down')),
          reason, f);
        log({ id: t.id, platform: t.platform, status: 'retry-requeued',
          note: note, error: errStr, retry: tries });
        out.push((t.id || f) + ' ' + t.platform + ' RETRY ' + tries +
          '/' + RETRY_MAX + ': ' + note);
        continue;
      }
      // the bumped counter could not be persisted - do NOT requeue
      // without it (an unbounded requeue is exactly what the bound
      // exists to prevent): fall through and fail the file
      // permanently, the same outcome as an exhausted budget.
    }
    mv(claimed, Q + '/failed/' + f, f);
    // transport loss AFTER the publish call was sent can mean the
    // post is already live while no post-created record exists - a
    // re-approve would post a SECOND copy. Say so everywhere: the
    // failed line, the status file and the ledger record
    // (maybe_live). Any external_id the orphan probe recovered
    // travels on e.orphan_id.
    const maybeLive = !!(e && e.maybe_live);
    const warn = maybeLive
      ? ' | POST MAY BE LIVE - check the platform feed before ' +
        'retrying' : '';
    // never leave a stale 'ok' behind - every failure path rewrites
    // vk_status. env_token_auth_error = the refresh service is down
    // AND the env fallback token was rejected too (vkCall flags both -
    // 'token_service_down' alone would mask the dead env credential);
    // token_service_down = host refresh service unreachable or unable
    // to mint a token; state_write_error = the refresh service minted
    // a token but persisting it to the state dir threw (ENOSPC/
    // EACCES) - a local FS failure that must not read as a
    // token-service outage; auth_error = VK API rejected the token
    // (error 5); vk_error = any other VK API rejection;
    // publish_error = transport / config / anything else. (A transient
    // retryable error only reaches here once its requeue budget is
    // exhausted or the counter could not be persisted - the
    // retryNote below makes the permanence explicit.)
    const retryNote = exhausted
      ? ' | ' + (e && e.vk_transient
        ? 'transient vk error retry budget exhausted (' + RETRY_MAX +
          ' requeues) - permanent failure; check VK-side limits, ' +
          'then re-approve'
        : (e && e.li_status
          ? 'transient linkedin api retry budget exhausted (' +
            RETRY_MAX + ' requeues) - permanent failure; check ' +
            'LinkedIn rate limits / api status, then re-approve'
          : 'token service retry budget exhausted (' + RETRY_MAX +
            ' requeues) - permanent failure; fix vk-token.service, ' +
            'then re-approve'))
      : (e && e.retryable)
        ? ' | retry counter could not be persisted - failed ' +
          'permanently rather than requeue unbounded'
        : '';
    const reason = (errStr + warn + retryNote +
      (e && e.refresh_error ? ' | refresh: ' + e.refresh_error : '') +
      (e && e.env_token_auth ? ' | env token also rejected (error 5)' : '')
      ).slice(0, 240);
    // per-platform status writer: a LinkedIn file's failure must not
    // headline vk_status.json (and a VK file never touches
    // linkedin_status.json)
    const sfn = p === 'linkedin' ? liStatus : vkStatus;
    if (e && e.token_service && e.env_token_auth)
      sfn('env_token_auth_error', reason, f);
    else if (e && e.token_service) sfn('token_service_down', reason, f);
    else if (e && e.state_write) sfn('state_write_error', reason, f);
    else if (e && e.vk_code === 5) sfn('auth_error', reason, f);
    else if (e && e.vk_code) sfn('vk_error', reason, f);
    // linkedin auth rejection (401/403): the same terminal 'token
    // dead' headline as a VK error-5 - the operator re-runs the
    // platform's credential flow, not a service restart
    else if (e && e.li_auth) sfn('auth_error', reason, f);
    else if (e && e.li_status) sfn('api_error', reason, f);
    else sfn('publish_error', reason, f);
    log({ id: t.id, platform: t.platform, status: 'failed',
      maybe_live: maybeLive,
      // e.orphan_id is also how the ledger-append-failure path (a
      // post-created write that could not land after wall.post
      // succeeded) hands the post id downstream - publish.jsonl must
      // carry it too, not only the ledger record attempted below
      external_id: (e && e.orphan_id) || null, error: errStr });
    try {
      fs.appendFileSync(LEDGER, JSON.stringify({
        ts: new Date().toISOString(), id: t.id, platform: t.platform,
        status: 'failed', maybe_live: maybeLive,
        external_id: (e && e.orphan_id) || null, error: errStr
      }) + '\n');
    } catch (e2) {}
    // registry: mirrors the failed/ ledger record - maybe_live flags
    // transport loss where the post may have landed, external_ids
    // carries the id the orphan probe recovered (absent on an empty
    // probe)
    registryEvent({ post_id: t.post_id, draft_id: t.id, platform: p,
      stage: 'publish', status: 'failed', writer: 'sp-publish',
      error: errStr, maybe_live: maybeLive || undefined,
      external_ids: (e && e.orphan_id) ? [e.orphan_id] : undefined });
    out.push((t.id || f) + ' ' + t.platform + ' FAILED: ' +
      errStr.slice(0, 150) +
      (t.post_id ? ' ' + t.post_id : '') +
      (maybeLive ? ' | POST MAY BE LIVE - check VK wall before retry' : '') +
      (exhausted ? ' | retries exhausted - ' +
        (e && e.vk_transient ? 'check VK-side limits'
          : 'fix vk-token.service') + ', re-approve' : ''));
  }
}
// merge this tick's per-file results: vk_status.json reports the WORST
// status plus the per-file detail array, so a clean file can no longer
// overwrite an earlier file's auth_error from the same run
// shared status ranking: the VK and LinkedIn per-platform merges
// below use the same weights - a status change lands in one place
const statusRank = (s) => ({
    // 'skipped' is informational only - the file was parked, not a
    // driver outcome - so it ranks BELOW 'ok': a mixed tick reports
    // the real publish result, only a skip-only tick headlines it
    skipped: -1,
    ok: 0,
    // transient busy is informational only - the file was requeued,
    // not failed. It ranks above ok/no-work so a busy-only tick still
    // headlines it, but below EVERY real outcome: a busy file earlier
    // in the tick must never mask a publish_unverified or an error
    // status that came after it
    token_service_busy: 1, vk_transient: 1, api_transient: 1,
    publish_unverified: 2, test_delete_failed: 3,
    // a corrupt queue file is terminal (failed/) like a driver error
    // and must outrank ok/skipped so it can headline the tick
    bad_json: 4,
    // a stuck-claim recovery parked the file in failed/ - a real,
    // maybe-live failure, so it headlines with the same weight as a
    // driver publish_error (and above publish_unverified, which at
    // least saw a wall.post response)
    stuck_claim_recovered: 4,
    publish_error: 4, vk_error: 5, api_error: 5, auth_error: 6,
    token_service_down: 7,
    // two failures at once (refresh service down + env token dead) -
    // the worst headline a tick can report. state_write_error ranks
    // with it: the refresh succeeded but the state-dir write failed,
    // and the accompanying error-5 can mean the env credential is
    // dead too - never let an 'ok' or a lesser status mask a broken
    // state volume.
    env_token_auth_error: 8, state_write_error: 8
  })[s] ?? 4;
if (tickFiles.length) {
  const worst = tickFiles.reduce((a, b) =>
    statusRank(b.status) > statusRank(a.status) ? b : a, tickFiles[0]);
  try {
    const now = new Date().toISOString();
    writeJsonAtomic(VK_STATUS, {
      status: worst.status, ts: now, last_tick: now,
      file: worst.file, reason: worst.reason, files: tickFiles
    });
  } catch (e) {}
} else {
  // an empty tick (no queue files at all) reaches neither vkStatus
  // nor the merge above, so the status file kept the LAST non-empty
  // tick's ts forever - nothing proved the tick was still alive and
  // a stale headline read as current state. Rewrite the file with
  // the previous headline intact (a parked auth_error must not flip
  // to 'idle' just because the queue drained) and stamp last_tick
  // as the heartbeat; a fresh install with no prior file reports
  // 'idle'.
  try {
    let prev = {};
    try {
      prev = JSON.parse(fs.readFileSync(VK_STATUS, 'utf8')) || {};
    } catch (e) {}
    writeJsonAtomic(VK_STATUS, {
      status: prev.status || 'idle',
      ts: prev.ts || new Date().toISOString(),
      last_tick: new Date().toISOString(),
      file: prev.file || '', reason: prev.reason || '',
      files: Array.isArray(prev.files) ? prev.files : []
    });
  } catch (e) {}
}
// LinkedIn: the same merge on its own status file - a vk-only tick
// never rewrites the LinkedIn headline, and the empty-tick branch
// stamps the same last_tick heartbeat (idle only when no prior
// headline exists)
if (liTickFiles.length) {
  const worst = liTickFiles.reduce((a, b) =>
    statusRank(b.status) > statusRank(a.status) ? b : a,
    liTickFiles[0]);
  try {
    const now = new Date().toISOString();
    writeJsonAtomic(LI_STATUS, {
      status: worst.status, ts: now, last_tick: now,
      file: worst.file, reason: worst.reason, files: liTickFiles
    });
  } catch (e) {}
} else {
  try {
    let prev = {};
    try {
      prev = JSON.parse(fs.readFileSync(LI_STATUS, 'utf8')) || {};
    } catch (e) {}
    writeJsonAtomic(LI_STATUS, {
      status: prev.status || 'idle',
      ts: prev.ts || new Date().toISOString(),
      last_tick: new Date().toISOString(),
      file: prev.file || '', reason: prev.reason || '',
      files: Array.isArray(prev.files) ? prev.files : []
    });
  } catch (e) {}
}
if (out.length && chatId && token) {
  // Telegram rejects sendMessage over ~4096 chars and the catch below
  // swallows the failure - an unbounded tick report would be lost
  // silently. Cap it under the limit and mark the truncation so a cut
  // report reads as incomplete. Slice on code points (Array.from), not
  // UTF-16 units: a boundary split inside a surrogate pair would
  // produce a lone surrogate Telegram rejects as invalid text.
  let summary = 'Publish queue:\n' + out.join('\n');
  const summaryChars = Array.from(summary);
  if (summaryChars.length > 3900) {
    summary = summaryChars.slice(0, 3900).join('') +
      '\n... [truncated - ' + out.length + ' results total]';
  }
  try {
    await tg('sendMessage', { chat_id: chatId, text: summary });
  } catch (e) {
    // a lost tick report must not vanish without a trace:
    // the per-file records are already in publish.jsonl,
    // add a line saying the summary itself failed. Scrub
    // like every other error surface - the httpRequest
    // error can echo request details (bot-token URL).
    try {
      log({ action: 'summary-failed',
        error: scrub(e && (e.description || e.message) || e)
          .slice(0, 300) });
    } catch (e2) {}
  }
}
return [{ json: { processed: out.length, results: out } }];
